-- Phase 2 Plan 02: Phase 2 tables migration
-- Tables: workflows, workflow_versions, workflow_runs, activity_entries, approvals,
--         threads, messages, memory_items, memory_embeddings, brand_voice_profiles,
--         brand_voice_samples, autonomy_thresholds, shopify_products,
--         shopify_product_variants, shopify_orders, shopify_pages, shopify_redirects,
--         shopify_sync_state, gmail_threads, gmail_messages, gmail_sync_state,
--         agent_telemetry, cost_aggregates
--         (+ ALTER TABLE user_profiles ADD COLUMN onboarding_step)
-- Generated by: hand-authored from Drizzle schemas (drizzle-kit generate then adapted)
-- Applied via: npx supabase db push
-- DO NOT run drizzle-kit migrate against Supabase (RESEARCH.md Pitfall 2)
--
-- Cross-schema FKs to auth.users added manually (Drizzle cannot cross schemas)
-- update_updated_at_column() trigger function ALREADY EXISTS from migration 0002 — reused, not redefined

-- ─── pgvector extension (MUST be first) ──────────────────────────────────────

CREATE EXTENSION IF NOT EXISTS vector;

-- ─── workflows ────────────────────────────────────────────────────────────────

CREATE TABLE IF NOT EXISTS "workflows" (
    "id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL,
    "user_id" uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE,
    "name" text NOT NULL,
    "description" text,
    "automation_level" text NOT NULL DEFAULT 'L2',
    "status" text NOT NULL DEFAULT 'draft',
    "trigger_type" text NOT NULL,
    "trigger_config" jsonb NOT NULL DEFAULT '{}',
    "current_version_id" uuid,
    "source" text NOT NULL DEFAULT 'chat',
    "source_reference_id" uuid,
    "created_at" timestamp with time zone DEFAULT now() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT now() NOT NULL
);

ALTER TABLE "workflows" ENABLE ROW LEVEL SECURITY;

CREATE INDEX IF NOT EXISTS "idx_workflows_user_status" ON "workflows" USING btree ("user_id", "status");

CREATE POLICY "workflows_user_policy" ON "workflows"
    AS PERMISSIVE FOR ALL TO "authenticated"
    USING ((SELECT auth.uid()) = "workflows"."user_id")
    WITH CHECK ((SELECT auth.uid()) = "workflows"."user_id");

CREATE TRIGGER workflows_updated_at
    BEFORE UPDATE ON "workflows"
    FOR EACH ROW EXECUTE FUNCTION update_updated_at_column();

ALTER TABLE "workflows"
    ADD CONSTRAINT workflows_automation_level_check
        CHECK (automation_level IN ('L1', 'L2', 'L3')),
    ADD CONSTRAINT workflows_status_check
        CHECK (status IN ('active', 'paused', 'draft', 'archived'));

-- ─── workflow_versions ────────────────────────────────────────────────────────

CREATE TABLE IF NOT EXISTS "workflow_versions" (
    "id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL,
    "workflow_id" uuid NOT NULL REFERENCES "workflows"(id) ON DELETE CASCADE,
    "version_number" integer NOT NULL,
    "definition" jsonb NOT NULL,
    "schema_version" integer NOT NULL DEFAULT 1,
    "created_at" timestamp with time zone DEFAULT now() NOT NULL,
    "created_by_thread_id" uuid,
    CONSTRAINT "workflow_versions_workflow_version_unique" UNIQUE ("workflow_id", "version_number")
);

CREATE INDEX IF NOT EXISTS "idx_workflow_versions_workflow" ON "workflow_versions" USING btree ("workflow_id");

-- Add deferred FK: workflows.current_version_id → workflow_versions.id
-- (FK declared after workflow_versions table exists to resolve circular dependency)
ALTER TABLE "workflows"
    ADD CONSTRAINT "workflows_current_version_id_fk"
    FOREIGN KEY ("current_version_id") REFERENCES "workflow_versions"(id)
    DEFERRABLE INITIALLY DEFERRED;

-- ─── workflow_runs ────────────────────────────────────────────────────────────

CREATE TABLE IF NOT EXISTS "workflow_runs" (
    "id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL,
    "user_id" uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE,
    "workflow_id" uuid NOT NULL REFERENCES "workflows"(id) ON DELETE CASCADE,
    "workflow_version_id" uuid NOT NULL REFERENCES "workflow_versions"(id),
    "workflow_version_snapshot" jsonb NOT NULL,
    "trigger_source" text NOT NULL,
    "status" text NOT NULL,
    "current_step_id" text,
    "inngest_function_id" text,
    "error_summary" text,
    "metadata" jsonb DEFAULT '{}',
    "started_at" timestamp with time zone DEFAULT now() NOT NULL,
    "completed_at" timestamp with time zone
);

ALTER TABLE "workflow_runs" ENABLE ROW LEVEL SECURITY;

CREATE INDEX IF NOT EXISTS "idx_workflow_runs_user_workflow" ON "workflow_runs" USING btree ("user_id", "workflow_id", "started_at" DESC);
CREATE INDEX IF NOT EXISTS "idx_workflow_runs_status" ON "workflow_runs" USING btree ("status") WHERE status IN ('queued', 'running', 'paused_for_approval', 'paused_manual');

CREATE POLICY "workflow_runs_user_policy" ON "workflow_runs"
    AS PERMISSIVE FOR ALL TO "authenticated"
    USING ((SELECT auth.uid()) = "workflow_runs"."user_id")
    WITH CHECK ((SELECT auth.uid()) = "workflow_runs"."user_id");

ALTER TABLE "workflow_runs"
    ADD CONSTRAINT workflow_runs_status_check
        CHECK (status IN ('queued', 'running', 'paused_for_approval', 'paused_manual', 'succeeded', 'failed', 'expired'));

