CREATE INDEX IF NOT EXISTS "idx_activity_target" ON "activity_entries" USING btree ("target_type", "target_id");

-- Idempotency constraint (WF-06): prevent duplicate activity entries on Inngest retry.
-- Partial: only enforced when both workflow_run_id AND step_id are non-null.
CREATE UNIQUE INDEX IF NOT EXISTS "activity_entries_run_step_unique"
    ON "activity_entries" ("workflow_run_id", "step_id")
    WHERE workflow_run_id IS NOT NULL AND step_id IS NOT NULL;

CREATE POLICY "activity_entries_user_policy" ON "activity_entries"
