    WITH CHECK ((SELECT auth.uid()) = "gmail_sync_state"."user_id");

-- ─── agent_telemetry ──────────────────────────────────────────────────────────

CREATE TABLE IF NOT EXISTS "agent_telemetry" (
    "id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL,
    "user_id" uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE,
    "call_type" text NOT NULL,
    "workflow_run_id" uuid REFERENCES "workflow_runs"(id),
    "thread_id" uuid REFERENCES "threads"(id),
    "message_id" uuid REFERENCES "messages"(id),
    "model_id" text NOT NULL,
    "prompt_tokens" integer NOT NULL,
    "completion_tokens" integer NOT NULL,
    "total_tokens" integer NOT NULL,
    "cost_usd" numeric(10, 6),
    "latency_ms" integer NOT NULL,
    "success" boolean NOT NULL,
    "error_class" text,
    "tools_invoked" text[],
    "occurred_at" timestamp with time zone DEFAULT now() NOT NULL
);

ALTER TABLE "agent_telemetry" ENABLE ROW LEVEL SECURITY;

CREATE INDEX IF NOT EXISTS "idx_telemetry_user_time" ON "agent_telemetry" USING btree ("user_id", "occurred_at" DESC);

CREATE POLICY "agent_telemetry_user_policy" ON "agent_telemetry"
    AS PERMISSIVE FOR ALL TO "authenticated"
    USING ((SELECT auth.uid()) = "agent_telemetry"."user_id")
    WITH CHECK ((SELECT auth.uid()) = "agent_telemetry"."user_id");

-- ─── cost_aggregates ──────────────────────────────────────────────────────────

CREATE TABLE IF NOT EXISTS "cost_aggregates" (
    "user_id" uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE,
    "day" date NOT NULL,
    "total_tokens" bigint NOT NULL DEFAULT 0,
    "total_cost_usd" numeric(10, 4) NOT NULL DEFAULT 0,
    "llm_calls" integer NOT NULL DEFAULT 0,
    "workflow_runs" integer NOT NULL DEFAULT 0,
    PRIMARY KEY ("user_id", "day")
);

ALTER TABLE "cost_aggregates" ENABLE ROW LEVEL SECURITY;

CREATE POLICY "cost_aggregates_user_policy" ON "cost_aggregates"
    AS PERMISSIVE FOR ALL TO "authenticated"
    USING ((SELECT auth.uid()) = "cost_aggregates"."user_id")
    WITH CHECK ((SELECT auth.uid()) = "cost_aggregates"."user_id");

